fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let colw: i32 = w / 20;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut i: i32 = 0;
        while i < 20 {
            host::display::state_set(8 + i, 240 - i * 11);
            i = i + 1;
        }
    }
    let mut lvl = [0; 20];
    let mut i: i32 = 0;
    while i < 20 {
        lvl[i] = host::display::state_get(8 + i);
        i = i + 1;
    }
    if host::display::pointer_down() == 1 {
        let mut c: i32 = host::display::pointer_x() / colw;
        if c < 0 { c = 0; }
        if c > 19 { c = 19; }
        lvl[c] = lvl[c] + 6;
        if lvl[c] > 320 { lvl[c] = 320; }
    }
    i = 0;
    while i < 19 {
        let flow: i32 = (lvl[i] - lvl[i + 1]) / 8;
        lvl[i] = lvl[i] - flow;
        lvl[i + 1] = lvl[i + 1] + flow;
        i = i + 1;
    }
    let mut total: i32 = 0;
    i = 0;
    while i < 20 {
        host::display::state_set(8 + i, lvl[i]);
        total = total + lvl[i];
        i = i + 1;
    }
    host::display::clear(0x0c0c10);
    i = 0;
    while i < 20 {
        host::display::fill_rect(i * colw, h - lvl[i], colw - 1, lvl[i], 0x2060c0);
        host::display::fill_rect(i * colw, h - lvl[i], colw - 1, 3, 0x60a0e0);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "TOTAL", 0x606060, 1);
    host::display::draw_number(60, 8, total, 0x9090a0, 1);
    host::display::draw_string(8, 24, "HOLD TO POUR", 0x606060, 1);
    host::display::present();
}
